sys_ws_operation.operation_script:
(function process(request, response) {
    var requestBody = request.body.nextEntry();

    // 1. Generate an MD5 hash of the payload to enforce data idempotency
    var stringPayload = JSON.stringify(requestBody);
    var crypt = typeof GlideDigest == 'undefined' ? new CertificateEncryption() : new GlideDigest();
    var payloadHash = crypt.getMD5Hex(stringPayload);

    // Check for duplicate sensor hits to prevent redundant processing costs
    var checkDup = new GlideRecord('x_704340_metro_v_0_vault_safety_incident'); // *** REPLACE with your actual scoped table name ***
    checkDup.addQuery('u_payload_hash', payloadHash);
    checkDup.query();
    if(checkDup.next()) {
        response.setStatus(200);
        response.setBody({ "status": "Ignored", "message": "Duplicate telemetry payload detected." });
        return;
    }
// 2. Initialize a live record on your custom Vault Incident table
    var gr = new GlideRecord('x_704340_metro_v_0_vault_safety_incident'); // *** REPLACE with your actual scoped table name ***
    gr.initialize();
    gr.short_description = "Telemetry Alert: " + requestBody.vault_id;

    // Standardize input properties for the AI processor
    gr.description = "VAULT_ID: " + requestBody.vault_id + " // WATER_LEVEL: " + requestBody.water_level_inches + " INCHES // TEMP: " + requestBody.vault_temp_c + "C // PUMP_STATE: " + requestBody.pump_status;
    gr.u_payload_hash = payloadHash;

    var createdSysId = gr.insert();

    // 3. Respond back to the sensor device
    var res = {};
    res.status = "Success";
    res.vault_incident_created = createdSysId;
    response.setBody(res);
    response.setStatus(201);
})(request, response);
